replacements.newString:
test("client IP is derived from forwarded headers when present", () => {
  const headers = new Headers({ "x-forwarded-for": "198.51.100.7, 10.0.0.5" });

  assert.equal(getClientIp(headers), "198.51.100.7");
});

test("redirect URLs are limited to safe http and https destinations", () => {
  assert.equal(isSafeRedirectUrl("https://example.com/path"), true);
  assert.equal(isSafeRedirectUrl("http://example.com"), true);
  assert.equal(isSafeRedirectUrl("javascript:alert(1)"), false);
  assert.equal(isSafeRedirectUrl("ftp://example.com"), false);
  assert.equal(isSafeRedirectUrl("http://127.0.0.1"), false);
  assert.equal(isSafeRedirectUrl("http://localhost"), false);
});
